            raise ValueError("y_pred must contain only integers")
    if average not in _JACCARD_AVERAGES:
        raise ValueError(
            "average must be one of None, 'micro', 'macro', 'weighted'"
        )

    if labels is None:
        label_order = sorted(set(y_true) | set(y_pred))
    else:
